// src/lib/post-funding/signatures.ts
//
// E-signatures for the post-funding client email sequence, one per in-house
// advisor. The HTML is the advisor's customesignature.com block pasted VERBATIM
// — it is trusted company content, rendered raw into the email. Never build one
// of these from user input.
//
// Keyed by the advisor's `advisors.email` in the vault (lowercase), which is
// not always the address the signature shows: Matt logs in as
// matt@mrmcapitalgroup.com but signs as matt@shieldadvisorygroup.com. `replyTo`
// is the address printed in the signature, so a reply goes where the client
// expects it to.
//
// Any advisor without an entry (every external partner, test accounts) signs
// with Luigi's — by decision, Luigi is the contact for those clients. See
// resolveSignature().
//
// `bookingUrl` is the advisor's own scheduling page (the destination of the
// signature's "book a call" button, with the tracking redirect stripped) and
// backs every "schedule a call" button in the sequence.

export interface AdvisorSignature {
  name: string;
  title: string;
  phone: string;
  replyTo: string;
  bookingUrl: string;
  html: string;
}

