/**
 * The signature for a file's advisor, or Luigi's when the advisor has none
 * (test accounts, a file with no advisor at all).
 *
 * External advisors ALWAYS get Luigi, even if their email were ever added to
 * SIGNATURES — by decision, every external partner's client hears from Luigi.
 * `isFallback` lets callers report which files went out under Luigi's name.
 */
export function resolveSignature(
  advisorEmail: string | null | undefined,
  opts: { isExternal?: boolean } = {}
): {
  signature: AdvisorSignature;
  isFallback: boolean;
} {
  const key = (advisorEmail ?? "").trim().toLowerCase();
  const own = key && !opts.isExternal ? SIGNATURES[key] : undefined;
  if (own) return { signature: own, isFallback: false };
  return { signature: SIGNATURES[LUIGI_KEY], isFallback: true };
}
